.rm-t-minimal-mono .rm-item{margin-bottom:15px;}
.rm-t-minimal-mono .rm-item-t{font-size:14px;font-weight:600;letter-spacing:.01em;color:#0a0a0a;}
.rm-t-minimal-mono .rm-item-role{font-size:12px;color:#666666;}
.rm-t-minimal-mono .rm-date{font-size:10.5px;letter-spacing:.08em;color:#888888;}
.rm-t-minimal-mono .rm-item-sub{font-size:11.5px;color:#777777;}
.rm-t-minimal-mono .rm-edu-courses{font-size:11px;color:#777777;}
.rm-t-minimal-mono .rm-edu-courses .rm-k{font-size:9.5px;letter-spacing:.12em;color:#999999;}
.rm-t-minimal-mono .rm-bullets{padding-left:15px;}
.rm-t-minimal-mono .rm-bullets li{margin:3px 0;}
