.rm-t-sidebar-ink .rm-photo.rm-photo-contain-box{background:rgba(255,255,255,.10);}
.rm-t-sidebar-ink .rm-name{margin:0;font-size:29px;line-height:1.22;font-weight:600;letter-spacing:.06em;color:#f6faf8;}
.rm-t-sidebar-ink .rm-name::after{content:"";display:block;width:36px;height:3px;margin:14px 0 0;background:#c2a06a;}
