.rm-t-sidebar-ink .rm-k{font-size:9px;letter-spacing:.22em;color:#7f9d92;text-transform:uppercase;}
.rm-t-sidebar-ink .rm-v{font-size:11.5px;line-height:1.5;color:#e4efeb;overflow-wrap:anywhere;}
.rm-t-sidebar-ink .rm-body{grid-column:2;grid-row:1;padding:42px 42px 46px;}
.rm-t-sidebar-ink .rm-body > .rm-sec{margin-top:24px;}
.rm-t-sidebar-ink .rm-body > .rm-sec:first-child{margin-top:0;}
.rm-t-sidebar-ink .rm-sec-h{display:flex;align-items:center;gap:10px;margin:0 0 11px;}
